'use strict';
window.RHYMES = [
  {
    "authorBn": "\u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be",
    "authorEn": "Traditional folk rhyme",
    "category": "lullaby",
    "emoji": "\ud83c\udf19",
    "excerpt": false,
    "id": "chand-mama",
    "linesBn": [
      "\u0986\u09af\u09bc \u0986\u09af\u09bc \u099a\u09be\u0981\u09a6 \u09ae\u09be\u09ae\u09be \u099f\u09bf\u09aa \u09a6\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u0964",
      "\u099a\u09be\u0981\u09a6\u09c7\u09b0 \u0995\u09aa\u09be\u09b2\u09c7 \u099a\u09be\u0981\u09a6 \u099f\u09bf\u09aa \u09a6\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u0964",
      "\u09ae\u09be\u099b \u0995\u09c1\u099f\u09b2\u09c7 \u09ae\u09c1\u09a1\u09bc\u09cb \u09a6\u09c7\u09ac,",
      "\u09a7\u09be\u09a8 \u09ad\u09be\u09a8\u09b2\u09c7 \u0995\u09c1\u0981\u09a1\u09bc\u09cb \u09a6\u09c7\u09ac,",
      "\u0995\u09be\u09b2\u09cb \u0997\u09cb\u09b0\u09c1\u09b0 \u09a6\u09c1\u09a7 \u09a6\u09c7\u09ac,",
      "\u09a6\u09c1\u09a7 \u0996\u09be\u09ac\u09be\u09b0 \u09ac\u09be\u099f\u09bf \u09a6\u09c7\u09ac,",
      "\u099a\u09be\u0981\u09a6\u09c7\u09b0 \u0995\u09aa\u09be\u09b2\u09c7 \u099a\u09be\u0981\u09a6 \u099f\u09bf\u09aa \u09a6\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u0964"
    ],
    "linesRoman": [
      "Aay aay chand mama, tip diye ja.",
      "Chander kopale chand tip diye ja.",
      "Mach kutle muro debo,",
      "Dhan bhanle kunro debo,",
      "Kalo gorur dudh debo,",
      "Dudh khabar bati debo,",
      "Chander kopale chand tip diye ja."
    ],
    "meaningBn": "\u09ae\u09be \u099a\u09be\u0981\u09a6 \u09ae\u09be\u09ae\u09be\u0995\u09c7 \u09a1\u09be\u0995\u099b\u09c7\u09a8 \u09b6\u09bf\u09b6\u09c1\u09b0 \u0995\u09aa\u09be\u09b2\u09c7 \u099f\u09bf\u09aa \u09a6\u09bf\u09a4\u09c7; \u09ac\u09bf\u09a8\u09bf\u09ae\u09af\u09bc\u09c7 \u09ae\u09be\u099b, \u0995\u09c1\u0981\u09a1\u09bc\u09cb \u0986\u09b0 \u09a6\u09c1\u09a7 \u09a6\u09c7\u09ac\u09c7\u09a8\u0964",
    "meaningEn": "A mother calls Uncle Moon to put a lucky forehead dot on her baby, promising him fish, rice-husk and milk in return.",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 \u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be, \u09b0\u09ac\u09c0\u09a8\u09cd\u09a6\u09cd\u09b0\u09a8\u09be\u09a5 \u09a0\u09be\u0995\u09c1\u09b0\u09c7\u09b0 \u09e7\u09ee\u09ef\u09ea \u09b8\u09be\u09b2\u09c7\u09b0 \u09aa\u09cd\u09b0\u09ac\u09a8\u09cd\u09a7\u09c7 \u0989\u09a6\u09cd\u09a7\u09c3\u09a4",
    "sourceEn": "Public domain \u2014 anonymous folk rhyme, quoted in Rabindranath Tagore's 1894 essay on children's rhymes",
    "titleBn": "\u0986\u09af\u09bc \u0986\u09af\u09bc \u099a\u09be\u0981\u09a6 \u09ae\u09be\u09ae\u09be",
    "titleEn": "Aay Aay Chand Mama"
  },
  {
    "authorBn": "\u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be",
    "authorEn": "Traditional folk rhyme",
    "category": "fun",
    "emoji": "\ud83d\udc0c",
    "excerpt": false,
    "id": "hattimatim",
    "linesBn": [
      "\u09b9\u09be\u099f\u09cd\u099f\u09bf\u09ae\u09be\u099f\u09bf\u09ae \u099f\u09bf\u09ae,",
      "\u09a4\u09be\u09b0\u09be \u09ae\u09be\u09a0\u09c7 \u09aa\u09be\u09a1\u09bc\u09c7 \u09a1\u09bf\u09ae\u0964",
      "\u09a4\u09be\u09a6\u09c7\u09b0 \u0996\u09be\u09a1\u09bc\u09be \u09a6\u09c1\u099f\u09cb \u09b6\u09bf\u0982,",
      "\u09a4\u09be\u09b0\u09be \u09b9\u09be\u099f\u09cd\u099f\u09bf\u09ae\u09be\u099f\u09bf\u09ae \u099f\u09bf\u09ae\u0964"
    ],
    "linesRoman": [
      "Hattimatim tim,",
      "Tara mathe pare dim.",
      "Tader khara duto shing,",
      "Tara hattimatim tim."
    ],
    "meaningBn": "\u099b\u09cb\u099f\u09cd\u099f \u09b6\u09be\u09ae\u09c1\u0995\u09c7\u09b0\u09be \u09ae\u09be\u09a0\u09c7 \u09a1\u09bf\u09ae \u09aa\u09be\u09a1\u09bc\u09c7 \u2014 \u09b6\u09bf\u09b6\u09c1\u09a6\u09c7\u09b0 \u09aa\u09cd\u09b0\u09bf\u09af\u09bc \u098f\u0995\u099f\u09bf \u09ae\u099c\u09be\u09b0 \u099b\u09a1\u09bc\u09be\u0964",
    "meaningEn": "Tiny snails with two straight horns lay eggs in the field \u2014 a nonsense rhyme children love to chant.",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 \u09e7\u09ee\u09ef\u09ef \u09b8\u09be\u09b2\u09c7\u09b0 '\u0996\u09c1\u0996\u09c1\u09ae\u09a3\u09bf\u09b0 \u099b\u09a1\u09bc\u09be' (\u09b8\u0982\u0995\u09b2\u0995 \u09af\u09cb\u0997\u09c0\u09a8\u09cd\u09a6\u09cd\u09b0\u09a8\u09be\u09a5 \u09b8\u09b0\u0995\u09be\u09b0) \u0997\u09cd\u09b0\u09a8\u09cd\u09a5\u09c7 \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4; \u09ae\u09c2\u09b2 \u099b\u09a1\u09bc\u09be \u098f\u0987 \u09ea \u09b2\u09be\u0987\u09a8\u0987",
    "sourceEn": "Public domain \u2014 printed in 'Khukumonir Chhora' (1899), compiled by Jogindranath Sarkar; the original is these 4 lines",
    "titleBn": "\u09b9\u09be\u099f\u09cd\u099f\u09bf\u09ae\u09be\u099f\u09bf\u09ae \u099f\u09bf\u09ae",
    "titleEn": "Hattimatim Tim"
  },
  {
    "authorBn": "\u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be",
    "authorEn": "Traditional folk rhyme",
    "category": "birds",
    "emoji": "\ud83e\udd9c",
    "excerpt": false,
    "id": "ata-gache",
    "linesBn": [
      "\u0986\u09a4\u09be \u0997\u09be\u099b\u09c7 \u09a4\u09cb\u09a4\u09be \u09aa\u09be\u0996\u09bf",
      "\u09a1\u09be\u09b2\u09bf\u09ae \u0997\u09be\u099b\u09c7 \u09ae\u09cc",
      "\u098f\u09a4 \u09a1\u09be\u0995\u09bf \u09a4\u09ac\u09c1 \u0995\u09a5\u09be",
      "\u0995\u0993 \u09a8\u09be \u0995\u09c7\u09a8 \u09ac\u0989?"
    ],
    "linesRoman": [
      "Ata gache tota pakhi,",
      "Dalim gache mou.",
      "Eto daki tobu kotha,",
      "Kowna keno bou?"
    ],
    "meaningBn": "\u09a4\u09cb\u09a4\u09be \u09aa\u09be\u0996\u09bf \u09a1\u09be\u0995\u09b2\u09c7\u0993 \u0995\u09a5\u09be \u09ac\u09b2\u09c7 \u09a8\u09be \u2014 \u09b6\u09bf\u09b6\u09c1\u09a6\u09c7\u09b0 \u0996\u09c1\u09ac \u09aa\u09cd\u09b0\u09bf\u09af\u09bc \u098f\u0995\u099f\u09bf \u09ae\u099c\u09be\u09b0 \u099b\u09a1\u09bc\u09be\u0964",
    "meaningEn": "A parrot sits on the custard-apple tree and will not answer, no matter how much it is called.",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 \u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be",
    "sourceEn": "Public domain \u2014 anonymous folk rhyme",
    "titleBn": "\u0986\u09a4\u09be \u0997\u09be\u099b\u09c7 \u09a4\u09cb\u09a4\u09be \u09aa\u09be\u0996\u09bf",
    "titleEn": "Ata Gache Tota Pakhi"
  },
  {
    "authorBn": "\u09b8\u09c1\u0995\u09c1\u09ae\u09be\u09b0 \u09b0\u09be\u09af\u09bc (\u09e7\u09ee\u09ee\u09ed\u2013\u09e7\u09ef\u09e8\u09e9)",
    "authorEn": "Sukumar Ray (1887\u20131923)",
    "category": "fun",
    "emoji": "\ud83d\udc0d",
    "excerpt": false,
    "id": "baburam",
    "linesBn": [
      "\u09ac\u09be\u09ac\u09c1\u09b0\u09be\u09ae \u09b8\u09be\u09aa\u09c1\u09a1\u09bc\u09c7, \u0995\u09cb\u09a5\u09be \u09af\u09be\u09b8 \u09ac\u09be\u09aa\u09c1\u09b0\u09c7?",
      "\u0986\u09af\u09bc \u09ac\u09be\u09ac\u09be \u09a6\u09c7\u0996\u09c7 \u09af\u09be, \u09a6\u09c1\u099f\u09cb \u09b8\u09be\u09aa \u09b0\u09c7\u0996\u09c7 \u09af\u09be\u2014",
      "\u09af\u09c7 \u09b8\u09be\u09aa\u09c7\u09b0 \u099a\u09cb\u0996 \u09a8\u09c7\u0987, \u09b6\u09bf\u0982 \u09a8\u09c7\u0987 \u09a8\u09cb\u0996 \u09a8\u09c7\u0987,",
      "\u099b\u09cb\u099f\u09c7 \u09a8\u09be \u0995\u09bf \u09b9\u09be\u0981\u099f\u09c7 \u09a8\u09be, \u0995\u09be\u0989\u0995\u09c7 \u09af\u09c7 \u0995\u09be\u099f\u09c7 \u09a8\u09be,",
      "\u0995\u09b0\u09c7 \u09a8\u09be\u0995\u09cb \u09ab\u09cb\u0981\u09b8\u09ab\u09be\u0981\u09b8, \u09ae\u09be\u09b0\u09c7 \u09a8\u09be\u0995\u09cb \u09a2\u09c1\u0981\u09b6\u09a2\u09be\u0981\u09b6,",
      "\u09a8\u09c7\u0987 \u0995\u09cb\u09a8 \u0989\u09ce\u09aa\u09be\u09a4, \u0996\u09be\u09af\u09bc \u09b6\u09c1\u09a7\u09c1 \u09a6\u09c1\u09a7\u09ad\u09be\u09a4,",
      "\u09b8\u09c7 \u09b8\u09be\u09aa \u099c\u09cd\u09af\u09be\u09a8\u09cd\u09a4 \u0997\u09cb\u099f\u09be \u09a6\u09c1\u0987 \u0986\u09a8\u09be,",
      "\u09a4\u09c7\u09a1\u09bc\u09c7 \u09ae\u09c7\u09b0\u09c7 \u09a1\u09be\u09a3\u09cd\u09a1\u09be \u0995'\u09b0\u09c7 \u09a6\u09bf\u0987 \u09a0\u09be\u09a3\u09cd\u09a1\u09be\u0964"
    ],
    "linesRoman": [
      "Baburam sapure, kotha jas bapure?",
      "Aay baba dekhe ja, duto sap rekhe ja \u2014",
      "Je saper chokh nei, shing nei nokh nei,",
      "Chote na ki hate na, kauke je kate na,",
      "Kore nako foshfash, mare nako dhushdhash,",
      "Nei kono utpat, khay shudhu dudh-bhat,",
      "Se sap janto gota dui ana,",
      "Tere mere danda kore dii thanda."
    ],
    "meaningBn": "\u09b8\u09be\u09aa\u09c1\u09a1\u09bc\u09c7 \u09ac\u09be\u09ac\u09c1\u09b0\u09be\u09ae\u0995\u09c7 \u09ac\u09b2\u09be \u09b9\u099a\u09cd\u099b\u09c7 \u098f\u09ae\u09a8 \u09a6\u09c1\u099f\u09cb \u09b8\u09be\u09aa \u09b0\u09c7\u0996\u09c7 \u09af\u09c7\u09a4\u09c7, \u09af\u09be\u09a6\u09c7\u09b0 \u099a\u09cb\u0996 \u09a8\u09c7\u0987, \u0995\u09be\u09ae\u09a1\u09bc \u09a8\u09c7\u0987 \u2014 \u09b6\u09c1\u09a7\u09c1 \u09a6\u09c1\u09a7\u09ad\u09be\u09a4 \u0996\u09be\u09af\u09bc\u0964",
    "meaningEn": "Baburam the snake-charmer is asked to leave behind two snakes \u2014 ones with no eyes, no horns and no bite, that only eat milk and rice.",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 '\u0986\u09ac\u09cb\u09b2 \u09a4\u09be\u09ac\u09cb\u09b2' (\u09e7\u09ef\u09e8\u09e9) \u09a5\u09c7\u0995\u09c7",
    "sourceEn": "Public domain \u2014 from 'Abol Tabol' (1923)",
    "titleBn": "\u09ac\u09be\u09ac\u09c1\u09b0\u09be\u09ae \u09b8\u09be\u09aa\u09c1\u09a1\u09bc\u09c7",
    "titleEn": "Baburam Sapure"
  },
  {
    "authorBn": "\u09b0\u09ac\u09c0\u09a8\u09cd\u09a6\u09cd\u09b0\u09a8\u09be\u09a5 \u09a0\u09be\u0995\u09c1\u09b0 (\u09e7\u09ee\u09ec\u09e7\u2013\u09e7\u09ef\u09ea\u09e7)",
    "authorEn": "Rabindranath Tagore (1861\u20131941)",
    "category": "nature",
    "emoji": "\ud83c\udf34",
    "excerpt": true,
    "id": "talgach",
    "linesBn": [
      "\u09a4\u09be\u09b2\u0997\u09be\u099b \u098f\u0995 \u09aa\u09be\u09af\u09bc\u09c7 \u09a6\u09be\u0981\u09a1\u09bc\u09bf\u09af\u09bc\u09c7",
      "\u09b8\u09ac \u0997\u09be\u099b \u099b\u09be\u09a1\u09bc\u09bf\u09af\u09bc\u09c7",
      "\u0989\u0981\u0995\u09bf \u09ae\u09be\u09b0\u09c7 \u0986\u0995\u09be\u09b6\u09c7\u0964",
      "\u09ae\u09a8\u09c7 \u09b8\u09be\u09a7, \u0995\u09be\u09b2\u09cb \u09ae\u09c7\u0998 \u09ab\u09c1\u0981\u09a1\u09bc\u09c7 \u09af\u09be\u09af\u09bc",
      "\u098f\u0995\u09c7\u09ac\u09be\u09b0\u09c7 \u0989\u09a1\u09bc\u09c7 \u09af\u09be\u09af\u09bc;",
      "\u0995\u09cb\u09a5\u09be \u09aa\u09be\u09ac\u09c7 \u09aa\u09be\u0996\u09be \u09b8\u09c7?",
      "\u09a4\u09be\u0987 \u09a4\u09cb \u09b8\u09c7 \u09a0\u09bf\u0995 \u09a4\u09be\u09b0 \u09ae\u09be\u09a5\u09be\u09a4\u09c7",
      "\u0997\u09cb\u09b2 \u0997\u09cb\u09b2 \u09aa\u09be\u09a4\u09be\u09a4\u09c7",
      "\u0987\u099a\u09cd\u099b\u09be\u099f\u09bf \u09ae\u09c7\u09b2\u09c7 \u09a4\u09be\u09b0,",
      "\u09ae\u09a8\u09c7 \u09ae\u09a8\u09c7 \u09ad\u09be\u09ac\u09c7, \u09ac\u09c1\u099d\u09bf \u09a1\u09be\u09a8\u09be \u098f\u0987,",
      "\u0989\u09a1\u09bc\u09c7 \u09af\u09c7\u09a4\u09c7 \u09ae\u09be\u09a8\u09be \u09a8\u09c7\u0987",
      "\u09ac\u09be\u09b8\u09be\u0996\u09be\u09a8\u09bf \u09ab\u09c7\u09b2\u09c7 \u09a4\u09be\u09b0\u0964"
    ],
    "linesRoman": [
      "Talgach ek paye danriye,",
      "Sob gach chariye,",
      "Unki mare akashe.",
      "Mone sadh, kalo megh funre jay,",
      "Ekebare ure jay;",
      "Kotha pabe pakha se?",
      "Tai to se thik tar mathate,",
      "Gol gol patate,",
      "Ichchhati mele tar,",
      "Mone mone bhabe, bujhi dana ei,",
      "Ure jete mana nei,",
      "Basakhani fele tar."
    ],
    "meaningBn": "\u098f\u0995 \u09aa\u09be\u09af\u09bc\u09c7 \u09a6\u09be\u0981\u09a1\u09bc\u09bf\u09af\u09bc\u09c7 \u09a5\u09be\u0995\u09be \u09a4\u09be\u09b2\u0997\u09be\u099b\u09c7\u09b0 \u09ae\u09a8\u09c7 \u09b8\u09be\u09a7 \u2014 \u09aa\u09be\u09a4\u09be\u09b0 \u09a1\u09be\u09a8\u09be\u09af\u09bc \u09ad\u09b0 \u0995\u09b0\u09c7 \u0986\u0995\u09be\u09b6\u09c7 \u0989\u09a1\u09bc\u09c7 \u09af\u09be\u09ac\u09c7\u0964",
    "meaningEn": "A tall palm tree stands on one leg, dreaming it could fly away on its round leaves like wings.",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 '\u09b6\u09bf\u09b6\u09c1 \u09ad\u09cb\u09b2\u09be\u09a8\u09be\u09a5' (\u09e7\u09ef\u09e8\u09e8) \u09a5\u09c7\u0995\u09c7; \u09e8\u09ea \u09b2\u09be\u0987\u09a8\u09c7\u09b0 \u09aa\u09cd\u09b0\u09a5\u09ae \u09e7\u09e8 \u09b2\u09be\u0987\u09a8",
    "sourceEn": "Public domain \u2014 from 'Shishu Bholanath' (1922); first 12 of 24 lines",
    "titleBn": "\u09a4\u09be\u09b2\u0997\u09be\u099b",
    "titleEn": "Talgach (The Palm Tree)"
  },
  {
    "authorBn": "\u09b0\u09ac\u09c0\u09a8\u09cd\u09a6\u09cd\u09b0\u09a8\u09be\u09a5 \u09a0\u09be\u0995\u09c1\u09b0 (\u09e7\u09ee\u09ec\u09e7\u2013\u09e7\u09ef\u09ea\u09e7)",
    "authorEn": "Rabindranath Tagore (1861\u20131941)",
    "category": "nature",
    "emoji": "\ud83c\udf27\ufe0f",
    "excerpt": true,
    "id": "brishti",
    "linesBn": [
      "\u09a6\u09bf\u09a8\u09c7\u09b0 \u0986\u09b2\u09cb \u09a8\u09bf\u09ac\u09c7 \u098f\u09b2,",
      "\u09b8\u09c1\u09af\u09cd\u09af\u09bf \u09a1\u09cb\u09ac\u09c7-\u09a1\u09cb\u09ac\u09c7\u0964",
      "\u0986\u0995\u09be\u09b6 \u0998\u09bf\u09b0\u09c7 \u09ae\u09c7\u0998 \u099c\u09c1\u099f\u09c7\u099b\u09c7",
      "\u099a\u09be\u0981\u09a6\u09c7\u09b0 \u09b2\u09cb\u09ad\u09c7 \u09b2\u09cb\u09ad\u09c7\u0964",
      "\u09ae\u09c7\u0998\u09c7\u09b0 \u0989\u09aa\u09b0 \u09ae\u09c7\u0998 \u0995\u09b0\u09c7\u099b\u09c7,",
      "\u09b0\u0999\u09c7\u09b0 \u0989\u09aa\u09b0 \u09b0\u0999\u0964",
      "\u09ae\u09a8\u09cd\u09a6\u09bf\u09b0\u09c7\u09a4\u09c7 \u0995\u09be\u0981\u09b6\u09b0 \u0998\u09a3\u09cd\u099f\u09be",
      "\u09ac\u09be\u099c\u09b2 \u09a0\u0982 \u09a0\u0982\u0964",
      "\u0993 \u09aa\u09be\u09b0\u09c7\u09a4\u09c7 \u09ac\u09bf\u09b7\u09cd\u099f\u09bf \u098f\u09b2,",
      "\u099d\u09be\u09aa\u09b8\u09be \u0997\u09be\u099b\u09aa\u09be\u09b2\u09be\u0964",
      "\u098f \u09aa\u09be\u09b0\u09c7\u09a4\u09c7 \u09ae\u09c7\u0998\u09c7\u09b0 \u09ae\u09be\u09a5\u09be\u09af\u09bc",
      "\u098f\u0995\u09b6\u09cb \u09ae\u09be\u09a8\u09bf\u0995 \u099c\u09cd\u09ac\u09be\u09b2\u09be\u0964",
      "\u09ac\u09be\u09a6\u09b2\u09be \u09b9\u09be\u0993\u09af\u09bc\u09be\u09af\u09bc \u09ae\u09a8\u09c7 \u09aa\u09a1\u09bc\u09c7",
      "\u099b\u09c7\u09b2\u09c7\u09ac\u09c7\u09b2\u09be\u09b0 \u0997\u09be\u09a8\u2014",
      "\u09ac\u09bf\u09b7\u09cd\u099f\u09bf \u09aa\u09a1\u09bc\u09c7 \u099f\u09be\u09aa\u09c1\u09b0 \u099f\u09c1\u09aa\u09c1\u09b0,",
      "\u09a8\u09a6\u09c7\u09af\u09bc \u098f\u09b2 \u09ac\u09be\u09a8\u0964"
    ],
    "linesRoman": [
      "Diner alo nibhe elo,",
      "Sujji dobe-dobe.",
      "Akash ghire megh juteche",
      "Chander lobhe lobhe.",
      "Megher upor megh koreche,",
      "Ronger upor rong.",
      "Mondirete kanshor ghonta",
      "Bajlo thong thong.",
      "O parete bishti elo,",
      "Jhapsa gachpala.",
      "E parete megher mathay",
      "Eksho manik jala.",
      "Badla haway mone pore",
      "Chelebelar gan \u2014",
      "'Bishti pore tapur tupur,",
      "Nodey elo ban.'"
    ],
    "meaningBn": "\u099f\u09be\u09aa\u09c1\u09b0 \u099f\u09c1\u09aa\u09c1\u09b0 \u09ac\u09c3\u09b7\u09cd\u099f\u09bf \u0986\u09b0 \u09a8\u09a6\u09c0\u09b0 \u09ac\u09be\u09a8 \u09a6\u09c7\u0996\u09c7 \u0995\u09ac\u09bf\u09b0 \u09ae\u09a8\u09c7 \u09aa\u09a1\u09bc\u09c7 \u099b\u09c7\u09b2\u09c7\u09ac\u09c7\u09b2\u09be\u09b0 \u0997\u09be\u09a8 \u0986\u09b0 \u09ae\u09be\u09af\u09bc\u09c7\u09b0 \u09b9\u09be\u09b8\u09bf\u09ae\u09c1\u0996\u0964",
    "meaningEn": "Rain patters down, the river floods, and the poet remembers childhood songs, his mother's smile and rainy days.",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 '\u09ac\u09c3\u09b7\u09cd\u099f\u09bf \u09aa\u09a1\u09bc\u09c7 \u099f\u09be\u09aa\u09c1\u09b0 \u099f\u09c1\u09aa\u09c1\u09b0'; \u09aa\u09cd\u09b0\u09a5\u09ae \u09e7\u09ec \u09b2\u09be\u0987\u09a8",
    "sourceEn": "Public domain \u2014 'Brishti Pore Tapur Tupur'; opening 16 lines",
    "titleBn": "\u09ac\u09c3\u09b7\u09cd\u099f\u09bf \u09aa\u09a1\u09bc\u09c7 \u099f\u09be\u09aa\u09c1\u09b0 \u099f\u09c1\u09aa\u09c1\u09b0",
    "titleEn": "Brishti Pore Tapur Tupur"
  },
  {
    "authorBn": "\u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be",
    "authorEn": "Traditional folk rhyme",
    "category": "birds",
    "emoji": "\ud83d\udd4a\ufe0f",
    "excerpt": false,
    "id": "noton",
    "linesBn": [
      "\u09a8\u09cb\u099f\u09a8 \u09a8\u09cb\u099f\u09a8 \u09aa\u09be\u09af\u09bc\u09b0\u09be\u0997\u09c1\u09b2\u09bf",
      "\u099d\u09cb\u099f\u09a8 \u09ac\u09c7\u0981\u09a7\u09c7\u099b\u09c7,",
      "\u0993\u09aa\u09be\u09b0\u09c7\u09a4\u09c7 \u099b\u09c7\u09b2\u09c7\u09ae\u09c7\u09af\u09bc\u09c7",
      "\u09a8\u09be\u0987\u09a4\u09c7 \u09a8\u09c7\u09ae\u09c7\u099b\u09c7\u0964",
      "\u09a6\u09c1\u0987 \u09a7\u09be\u09b0\u09c7 \u09a6\u09c1\u0987 \u09b0\u09c1\u0987 \u0995\u09be\u09a4\u09b2\u09be",
      "\u09ad\u09c7\u09b8\u09c7 \u0989\u09a0\u09c7\u099b\u09c7,",
      "\u0995\u09c7 \u09a6\u09c7\u0996\u09c7\u099b\u09c7 \u0995\u09c7 \u09a6\u09c7\u0996\u09c7\u099b\u09c7",
      "\u09a6\u09be\u09a6\u09be \u09a6\u09c7\u0996\u09c7\u099b\u09c7\u0964",
      "\u09a6\u09be\u09a6\u09be\u09b0 \u09b9\u09be\u09a4\u09c7 \u0995\u09b2\u09ae \u099b\u09bf\u09b2",
      "\u099b\u09c1\u0981\u09a1\u09bc\u09c7 \u09ae\u09c7\u09b0\u09c7\u099b\u09c7,",
      "\u0989\u0983 \u09ac\u09a1\u09cd\u09a1 \u09b2\u09c7\u0997\u09c7\u099b\u09c7\u0964"
    ],
    "linesRoman": [
      "Noton noton payraguli,",
      "Jhoton bendheche,",
      "Oparete chelemeye",
      "Naite nemeche.",
      "Dui dhare dui rui-katla",
      "Bhese utheche,",
      "Ke dekheche, ke dekheche,",
      "Dada dekheche.",
      "Dadar hate kolom chilo,",
      "Chunre mereche,",
      "Uh! Boddo legeche."
    ],
    "meaningBn": "\u09aa\u09be\u09af\u09bc\u09b0\u09be\u0997\u09c1\u09b2\u09bf \u099d\u09cb\u099f\u09a8 \u09ac\u09c7\u0981\u09a7\u09c7\u099b\u09c7, \u0993\u09aa\u09be\u09b0\u09c7 \u099b\u09c7\u09b2\u09c7\u09ae\u09c7\u09af\u09bc\u09c7\u09b0\u09be \u09a8\u09be\u0987\u09a4\u09c7 \u09a8\u09c7\u09ae\u09c7\u099b\u09c7, \u0986\u09b0 \u09a6\u09be\u09a6\u09be \u0995\u09b2\u09ae \u099b\u09c1\u0981\u09a1\u09bc\u09c7 \u09ae\u09c7\u09b0\u09c7\u099b\u09c7\u0964",
    "meaningEn": "Pigeons flock together while children bathe across the river, big fish surface, and elder brother watches \u2014 then throws his pen!",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 \u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be; \u09aa\u09cd\u09b0\u09a5\u09ae \u09b6\u09cd\u09b0\u09c7\u09a3\u09bf\u09b0 \u09ac\u09be\u0982\u09b2\u09be \u09ac\u0987\u09af\u09bc\u09c7 \u0986\u099b\u09c7",
    "sourceEn": "Public domain \u2014 anonymous folk rhyme; printed in Class 1 Bangla textbooks",
    "titleBn": "\u09a8\u09cb\u099f\u09a8 \u09a8\u09cb\u099f\u09a8 \u09aa\u09be\u09af\u09bc\u09b0\u09be\u0997\u09c1\u09b2\u09bf",
    "titleEn": "Noton Noton Payraguli"
  },
  {
    "authorBn": "\u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be",
    "authorEn": "Traditional folk rhyme",
    "category": "fun",
    "emoji": "\ud83e\udd41",
    "excerpt": false,
    "id": "agdum",
    "linesBn": [
      "\u0986\u0997\u09a1\u09c1\u09ae \u09ac\u09be\u0997\u09a1\u09c1\u09ae \u0998\u09cb\u09a1\u09bc\u09be\u09a1\u09c1\u09ae \u09b8\u09be\u099c\u09c7,",
      "\u09a2\u09be\u0995-\u09a2\u09cb\u09b2 \u099d\u09be\u0981\u099d\u09b0 \u09ac\u09be\u099c\u09c7\u0964",
      "\u09ac\u09be\u099c\u09a4\u09c7 \u09ac\u09be\u099c\u09a4\u09c7 \u099a\u09b2\u09b2 \u09a2\u09c1\u09b2\u09bf,",
      "\u09a2\u09c1\u09b2\u09bf \u0997\u09c7\u09b2 \u09b8\u09c7\u0987 \u0995\u09ae\u09b2\u09be\u09ab\u09c1\u09b2\u09bf\u0964",
      "\u0995\u09ae\u09b2\u09be\u09ab\u09c1\u09b2\u09bf\u09b0 \u099f\u09bf\u09af\u09bc\u09c7\u099f\u09be,",
      "\u09b8\u09c2\u09b0\u09cd\u09af\u09bf \u09ae\u09be\u09ae\u09be\u09b0 \u09ac\u09bf\u09af\u09bc\u09c7\u099f\u09be\u0964"
    ],
    "linesRoman": [
      "Agdum bagdum ghoradum saje,",
      "Dhak-dhol jhanjhor baje.",
      "Bajte bajte chollo dhuli,",
      "Dhuli gelo sei komlafuli.",
      "Komlafulir tiyeta,",
      "Surji mamar biyeta."
    ],
    "meaningBn": "\u09a2\u09be\u0995-\u09a2\u09cb\u09b2 \u09ac\u09be\u099c\u09bf\u09af\u09bc\u09c7 \u09ac\u09b0\u09af\u09be\u09a4\u09cd\u09b0\u09be \u099a\u09b2\u09c7\u099b\u09c7 \u0995\u09ae\u09b2\u09be\u09ab\u09c1\u09b2\u09bf\u09b0 \u09a6\u09bf\u0995\u09c7 \u2014 \u0986\u09a8\u09a8\u09cd\u09a6\u09c7\u09b0 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be\u0964",
    "meaningEn": "Drums and cymbals play as a wedding procession sets off for Kamalaphuli \u2014 a noisy, joyful folk rhyme.",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 \u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be; \u0985\u099e\u09cd\u099a\u09b2\u09ad\u09c7\u09a6\u09c7 \u09ac\u09be\u09a8\u09be\u09a8\u09c7 \u09ad\u09bf\u09a8\u09cd\u09a8\u09a4\u09be \u0986\u099b\u09c7",
    "sourceEn": "Public domain \u2014 anonymous folk rhyme; spellings vary by region (Dhuli/Duli, Komlafuli/Kamalaphuli)",
    "titleBn": "\u0986\u0997\u09a1\u09c1\u09ae \u09ac\u09be\u0997\u09a1\u09c1\u09ae",
    "titleEn": "Agdum Bagdum"
  },
  {
    "authorBn": "\u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be",
    "authorEn": "Traditional folk rhyme",
    "category": "fun",
    "emoji": "\ud83d\udc66",
    "excerpt": false,
    "id": "khokon",
    "linesBn": [
      "\u0996\u09cb\u0995\u09a8 \u0996\u09cb\u0995\u09a8 \u09a1\u09be\u0995 \u09aa\u09be\u09a1\u09bc\u09bf,",
      "\u0996\u09cb\u0995\u09a8 \u09ae\u09cb\u09a6\u09c7\u09b0 \u0995\u09be\u09b0 \u09ac\u09be\u09a1\u09bc\u09bf?",
      "\u0986\u09af\u09bc\u09b0\u09c7 \u0996\u09cb\u0995\u09a8 \u0998\u09b0\u09c7 \u0986\u09af\u09bc,",
      "\u09a6\u09c1\u09a7 \u09ae\u09be\u0996\u09be \u09ad\u09be\u09a4 \u0995\u09be\u0995\u09c7 \u0996\u09be\u09af\u09bc\u0964"
    ],
    "linesRoman": [
      "Khokon khokon dak pari,",
      "Khokon moder kar bari?",
      "Aayre khokon ghore aay,",
      "Dudh makha bhat kake khay."
    ],
    "meaningBn": "\u0996\u09cb\u0995\u09a8\u0995\u09c7 \u0998\u09b0\u09c7 \u09a1\u09be\u0995\u09be \u09b9\u099a\u09cd\u099b\u09c7 \u2014 \u09a6\u09c1\u09a7 \u09ae\u09be\u0996\u09be \u09ad\u09be\u09a4 \u0995\u09c7 \u0996\u09be\u09ac\u09c7?",
    "meaningEn": "Little Khokon is called home \u2014 who will eat the rice mixed with milk?",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 \u09aa\u09cd\u09b0\u099a\u09b2\u09bf\u09a4 \u09b2\u09cb\u0995\u099b\u09a1\u09bc\u09be",
    "sourceEn": "Public domain \u2014 anonymous folk rhyme",
    "titleBn": "\u0996\u09cb\u0995\u09a8 \u0996\u09cb\u0995\u09a8 \u09a1\u09be\u0995 \u09aa\u09be\u09a1\u09bc\u09bf",
    "titleEn": "Khokon Khokon Dak Pari"
  },
  {
    "authorBn": "\u09ae\u09a6\u09a8\u09ae\u09cb\u09b9\u09a8 \u09a4\u09b0\u09cd\u0995\u09be\u09b2\u0999\u09cd\u0995\u09be\u09b0 (\u09e7\u09ee\u09e7\u09ed\u2013\u09e7\u09ee\u09eb\u09ee)",
    "authorEn": "Madanmohan Tarkalankar (1817\u20131858)",
    "category": "morning",
    "emoji": "\ud83c\udf05",
    "excerpt": false,
    "id": "sokale",
    "linesBn": [
      "\u09b8\u0995\u09be\u09b2\u09c7 \u0989\u09a0\u09bf\u09af\u09bc\u09be \u0986\u09ae\u09bf \u09ae\u09a8\u09c7 \u09ae\u09a8\u09c7 \u09ac\u09b2\u09bf,",
      "\u09b8\u09be\u09b0\u09be\u09a6\u09bf\u09a8 \u0986\u09ae\u09bf \u09af\u09c7\u09a8 \u09ad\u09be\u09b2\u09cb \u09b9\u09af\u09bc\u09c7 \u099a\u09b2\u09bf\u0964",
      "\u0986\u09a6\u09c7\u09b6 \u0995\u09b0\u09c7\u09a8 \u09af\u09be\u09b9\u09be \u09ae\u09cb\u09b0 \u0997\u09c1\u09b0\u09c1\u099c\u09a8\u09c7,",
      "\u0986\u09ae\u09bf \u09af\u09c7\u09a8 \u09b8\u09c7\u0987 \u0995\u09be\u099c \u0995\u09b0\u09bf \u09ad\u09be\u09b2\u09cb \u09ae\u09a8\u09c7\u0964"
    ],
    "linesRoman": [
      "Sokale uthiya ami mone mone boli,",
      "Saradin ami jeno bhalo hoye choli.",
      "Adesh koren jaha mor gurujone,",
      "Ami jeno sei kaj kori bhalo mone."
    ],
    "meaningBn": "\u09b8\u0995\u09be\u09b2\u09c7 \u0993\u09a0\u09be\u09b0 \u09aa\u09cd\u09b0\u09a4\u09bf\u099c\u09cd\u099e\u09be \u2014 \u09b8\u09be\u09b0\u09be\u09a6\u09bf\u09a8 \u09ad\u09be\u09b2\u09cb \u09b9\u09af\u09bc\u09c7 \u099a\u09b2\u09be \u0986\u09b0 \u0997\u09c1\u09b0\u09c1\u099c\u09a8\u09c7\u09b0 \u0995\u09a5\u09be \u09ae\u09be\u09a8\u09be\u0964",
    "meaningEn": "A morning promise: wake up, think good thoughts, and obey your elders all day long.",
    "sourceBn": "\u09aa\u09be\u09ac\u09b2\u09bf\u0995 \u09a1\u09cb\u09ae\u09c7\u0987\u09a8 \u2014 '\u09b6\u09bf\u09b6\u09c1\u09b6\u09bf\u0995\u09cd\u09b7\u09be' (\u09e7\u09ee\u09ea\u09ef) \u09a5\u09c7\u0995\u09c7",
    "sourceEn": "Public domain \u2014 from 'Shishushiksha' (1849)",
    "titleBn": "\u09b8\u0995\u09be\u09b2\u09c7 \u0989\u09a0\u09bf\u09af\u09bc\u09be \u0986\u09ae\u09bf",
    "titleEn": "Sokale Uthiya Ami"
  }
];
